import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { animalService } from '../services/api';
import { Plus, Edit, Trash2, Eye, FileText, AlertTriangle } from 'lucide-react';
import toast from 'react-hot-toast';

const SPECIES = ['Keçi', 'Koyun', 'Sığır', 'Manda', 'Deve'];
const STATUS_LABELS = { active: 'Aktif', sold: 'Satıldı', dead: 'Öldü', lost: 'Kayıp' };
const STATUS_COLORS = { active: 'badge-success', sold: 'badge-info', dead: 'badge-danger', lost: 'badge-warning' };

const formatDateForInput = (d) => {
  if (!d) return '';
  if (typeof d === 'string' && d.includes('T')) return d.split('T')[0];
  return String(d).slice(0, 10);
};

const formatDate = (dateStr) => {
  if (!dateStr) return '—';
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return String(dateStr).slice(0, 10);
    return d.toLocaleDateString('tr-TR', { year: 'numeric', month: 'short', day: 'numeric' });
  } catch {
    return String(dateStr).slice(0, 10);
  }
};

// Animal Ekleme / Düzenleme Hızlı Modalı
function AnimalModal({ animal, farmId, onClose, onSaved }) {
  const isEdit = !!animal;
  const [form, setForm] = useState(() => {
    if (animal) {
      return {
        name: animal.name || '',
        code: animal.code || '',
        species: animal.species || 'Keçi',
        breed: animal.breed || '',
        birth_date: formatDateForInput(animal.birth_date),
        gender: animal.gender || 'F',
        color_description: animal.color_description || '',
        current_weight: animal.current_weight != null ? animal.current_weight : '',
        notes: animal.notes || ''
      };
    }
    return {
      name: '',
      code: '',
      species: 'Keçi',
      breed: '',
      birth_date: new Date().toISOString().split('T')[0],
      gender: 'F',
      color_description: '',
      current_weight: '',
      notes: ''
    };
  });
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name.trim() || !form.code.trim() || !form.birth_date) {
      toast.error('Ad, küpe no ve doğum tarihi zorunlu');
      return;
    }
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        code: form.code.trim(),
        species: form.species,
        breed: form.breed?.trim() || null,
        birth_date: form.birth_date,
        gender: form.gender,
        color_description: form.color_description?.trim() || null,
        current_weight: form.current_weight !== '' && form.current_weight != null ? parseFloat(form.current_weight) : null,
        notes: form.notes?.trim() || null
      };

      if (isEdit) {
        await animalService.update(animal.id, farmId, payload);
        toast.success('Hayvan güncellendi');
      } else {
        await animalService.create(farmId, payload);
        toast.success('Hayvan eklendi');
      }
      onSaved();
      onClose();
    } catch (err) {
      toast.error(err.response?.data?.error || 'İşlem başarısız');
    } finally {
      setSaving(false);
    }
  };

  const f = (key, val) => setForm(prev => ({ ...prev, [key]: val }));

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between p-5 border-b">
          <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2">
            {isEdit ? <><Edit className="w-5 h-5 text-blue-600" /> Hayvan Düzenle</> : <><Plus className="w-5 h-5 text-green-600" /> Yeni Hayvan Ekle</>}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 text-xl font-bold">✕</button>
        </div>

        <form onSubmit={handleSubmit} className="p-5 space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Hayvan Adı *</label>
              <input className="input-field" value={form.name} onChange={e => f('name', e.target.value)} placeholder="Çiçek" required />
            </div>
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Küpe No *</label>
              <input className="input-field font-mono" value={form.code} onChange={e => f('code', e.target.value)} placeholder="K001" required />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Tür *</label>
              <select className="input-field" value={form.species} onChange={e => f('species', e.target.value)}>
                {SPECIES.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Irk</label>
              <input className="input-field" value={form.breed} onChange={e => f('breed', e.target.value)} placeholder="Saanen" />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Doğum Tarihi *</label>
              <input type="date" className="input-field" value={form.birth_date} onChange={e => f('birth_date', e.target.value)} required />
            </div>
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Cinsiyet *</label>
              <select className="input-field" value={form.gender} onChange={e => f('gender', e.target.value)}>
                <option value="F">♀ Dişi</option>
                <option value="M">♂ Erkek</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Renk</label>
              <input className="input-field" value={form.color_description} onChange={e => f('color_description', e.target.value)} placeholder="Beyaz" />
            </div>
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Canlı Ağırlık (kg)</label>
              <input type="number" step="0.1" min="0" className="input-field" value={form.current_weight} onChange={e => f('current_weight', e.target.value)} placeholder="45.0" />
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-1">Notlar</label>
            <textarea className="input-field" rows={2} value={form.notes} onChange={e => f('notes', e.target.value)} placeholder="Ek notlar..." />
          </div>

          <div className="flex gap-3 pt-2">
            <button type="button" onClick={onClose} className="btn-secondary flex-1">İptal</button>
            <button type="submit" disabled={saving} className="btn-primary flex-1">
              {saving ? 'Kaydediliyor...' : (isEdit ? 'Güncelle' : 'Kaydet')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// Hayvan Çıkış / Durum Değişikliği Modalı
function ExitModal({ animal, farmId, onClose, onSaved }) {
  const [reason, setReason] = useState('sold');
  const [saving, setSaving] = useState(false);

  const handleConfirm = async () => {
    setSaving(true);
    try {
      await animalService.delete(animal.id, farmId, reason);
      toast.success(`Hayvan durumu güncellendi: ${STATUS_LABELS[reason] || reason}`);
      onSaved();
      onClose();
    } catch {
      toast.error('Çıkış işlemi başarısız');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6 animate-in fade-in">
        <div className="flex items-center gap-3 text-amber-600 mb-4">
          <AlertTriangle className="w-6 h-6 flex-shrink-0" />
          <h3 className="text-lg font-bold text-gray-900">Çiftlikten Çıkış / Durum Değiştir</h3>
        </div>

        <p className="text-sm text-gray-600 mb-4">
          <strong className="text-gray-900 font-semibold">{animal.name}</strong> ({animal.code}) kaydı için çıkış nedenini belirleyin:
        </p>

        <div className="space-y-2 mb-6">
          <label className="flex items-center gap-3 p-3 border rounded-xl cursor-pointer hover:bg-gray-50 transition-colors">
            <input type="radio" name="exit_reason" value="sold" checked={reason === 'sold'} onChange={() => setReason('sold')} className="text-green-600" />
            <div>
              <p className="text-sm font-bold text-gray-800">🏷️ Satıldı (sold)</p>
              <p className="text-xs text-gray-500">Hayvan başka bir çiftliğe veya pazara satıldı</p>
            </div>
          </label>

          <label className="flex items-center gap-3 p-3 border rounded-xl cursor-pointer hover:bg-gray-50 transition-colors">
            <input type="radio" name="exit_reason" value="dead" checked={reason === 'dead'} onChange={() => setReason('dead')} className="text-red-600" />
            <div>
              <p className="text-sm font-bold text-gray-800">❌ Öldü / İtlaf (dead)</p>
              <p className="text-xs text-gray-500">Doğal ölüm, hastalık veya zorunlu kesim</p>
            </div>
          </label>

          <label className="flex items-center gap-3 p-3 border rounded-xl cursor-pointer hover:bg-gray-50 transition-colors">
            <input type="radio" name="exit_reason" value="lost" checked={reason === 'lost'} onChange={() => setReason('lost')} className="text-amber-600" />
            <div>
              <p className="text-sm font-bold text-gray-800">❓ Kayıp / Çalındı (lost)</p>
              <p className="text-xs text-gray-500">Mera kaybı veya hırsızlık</p>
            </div>
          </label>
        </div>

        <div className="flex gap-3">
          <button type="button" onClick={onClose} className="btn-secondary flex-1">İptal</button>
          <button type="button" disabled={saving} onClick={handleConfirm} className="btn-primary flex-1 bg-red-600 hover:bg-red-700 border-none">
            {saving ? 'İşleniyor...' : 'Onayla ve Çıkar'}
          </button>
        </div>
      </div>
    </div>
  );
}

export default function AnimalsPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const farmId = user?.farm_id;

  const [animals, setAnimals] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [filters, setFilters] = useState({ status: 'active', species: '', search: '' });
  const [modal, setModal] = useState(null); // null | 'add' | animal object
  const [exitAnimal, setExitAnimal] = useState(null); // animal object for exit confirmation

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await animalService.list(farmId, page, 50, {
        status: filters.status || undefined,
        species: filters.species || undefined,
        search: filters.search || undefined
      });
      setAnimals(res.data.data || []);
      setTotal(res.data.pagination?.total || 0);
    } catch {
      toast.error('Hayvanlar yüklenemedi');
    } finally {
      setLoading(false);
    }
  }, [farmId, page, filters]);

  useEffect(() => { load(); }, [load]);

  return (
    <div className="space-y-4 pb-8">
      {/* Başlık ve Aksiyonlar */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
            🐐 Hayvan Yönetimi
          </h1>
          <p className="text-gray-500 text-sm">{total} kayıt listeleniyor</p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => navigate('/animals/new')}
            className="btn-secondary flex items-center gap-1.5 text-xs py-2 px-3 font-semibold"
            title="Geniş Form Sayfasında Ekle"
          >
            <FileText className="w-3.5 h-3.5 text-green-600" /> Detaylı Form
          </button>
          <button
            onClick={() => setModal('add')}
            className="btn-primary flex items-center gap-1.5 text-xs py-2 px-4 shadow-sm"
          >
            <Plus className="w-4 h-4" /> Hızlı Hayvan Ekle
          </button>
        </div>
      </div>

      {/* Filtreler */}
      <div className="card shadow-sm border border-gray-100">
        <div className="flex flex-wrap gap-3">
          <input
            type="text"
            placeholder="🔍 Ara (ad, küpe no)..."
            className="input-field flex-1 min-w-48"
            value={filters.search}
            onChange={e => { setFilters(p => ({ ...p, search: e.target.value })); setPage(1); }}
          />
          <select
            className="input-field w-36"
            value={filters.status}
            onChange={e => { setFilters(p => ({ ...p, status: e.target.value })); setPage(1); }}
          >
            <option value="">Tüm Durumlar</option>
            <option value="active">Aktif</option>
            <option value="sold">Satıldı</option>
            <option value="dead">Öldü</option>
            <option value="lost">Kayıp</option>
          </select>
          <select
            className="input-field w-36"
            value={filters.species}
            onChange={e => { setFilters(p => ({ ...p, species: e.target.value })); setPage(1); }}
          >
            <option value="">Tüm Türler</option>
            {SPECIES.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>
      </div>

      {/* Tablo / Kart Görünümü */}
      <div className="card p-0 overflow-hidden border-none shadow-none bg-transparent lg:bg-white lg:border lg:shadow-sm">
        {loading ? (
          <div className="flex items-center justify-center h-48 bg-white rounded-2xl">
            <div className="w-8 h-8 border-4 border-green-600 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : animals.length === 0 ? (
          <div className="text-center py-16 text-gray-400 bg-white rounded-2xl border border-gray-100">
            <div className="text-5xl mb-3">🐐</div>
            <p className="font-semibold text-gray-600">Hayvan bulunamadı</p>
            <p className="text-xs text-gray-400 mt-1">Filtre kriterlerinizi değiştirebilir veya yeni hayvan ekleyebilirsiniz.</p>
            <button onClick={() => setModal('add')} className="mt-4 btn-primary text-xs py-2 px-4 inline-flex items-center gap-1">
              <Plus className="w-3.5 h-3.5" /> İlk Hayvanı Ekle
            </button>
          </div>
        ) : (
          <>
            {/* Desktop Table */}
            <div className="hidden lg:block overflow-x-auto bg-white rounded-2xl border border-gray-100 shadow-sm">
              <table className="w-full text-sm">
                <thead className="bg-gray-50 text-gray-500 uppercase text-[10px] tracking-wider font-bold border-b border-gray-100">
                  <tr>
                    <th className="text-left px-6 py-4">Hayvan</th>
                    <th className="text-left px-6 py-4">Küpe No</th>
                    <th className="text-left px-6 py-4">Tür / Irk</th>
                    <th className="text-left px-6 py-4">Doğum Tarihi</th>
                    <th className="text-left px-6 py-4">Cinsiyet</th>
                    <th className="text-left px-6 py-4">Canlı Ağırlık</th>
                    <th className="text-left px-6 py-4">Durum</th>
                    <th className="text-right px-6 py-4">İşlemler</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {animals.map(a => (
                    <tr key={a.id} className="hover:bg-green-50/30 transition-colors group">
                      <td className="px-6 py-4">
                        <button
                          onClick={() => navigate(`/animals/${a.id}?farm_id=${farmId}`)}
                          className="font-bold text-gray-900 hover:text-green-700 text-left transition-colors"
                        >
                          {a.name}
                        </button>
                      </td>
                      <td className="px-6 py-4 text-gray-600 font-mono text-xs">{a.code}</td>
                      <td className="px-6 py-4 text-gray-600">
                        <span className="text-xs font-semibold px-2 py-0.5 bg-gray-100 rounded-md mr-1.5">{a.species}</span>
                        {a.breed && <span className="text-gray-400 text-xs italic">{a.breed}</span>}
                      </td>
                      <td className="px-6 py-4 text-gray-500 text-xs">{formatDate(a.birth_date)}</td>
                      <td className="px-6 py-4 font-medium text-xs">
                        {a.gender === 'F' ? (
                          <span className="text-pink-600 bg-pink-50 px-2 py-0.5 rounded-full font-bold">♀ Dişi</span>
                        ) : (
                          <span className="text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full font-bold">♂ Erkek</span>
                        )}
                      </td>
                      <td className="px-6 py-4 text-gray-600 font-semibold text-xs">
                        {a.current_weight ? `${a.current_weight} kg` : '—'}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`badge ${STATUS_COLORS[a.status] || 'badge-info'} text-xs font-semibold`}>
                          {STATUS_LABELS[a.status] || a.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-1.5 opacity-80 group-hover:opacity-100 transition-opacity">
                          <button
                            onClick={() => navigate(`/animals/${a.id}?farm_id=${farmId}`)}
                            className="p-1.5 text-teal-600 hover:bg-teal-50 rounded-lg transition-colors"
                            title="Kart Detayı"
                          >
                            <Eye className="w-4 h-4" />
                          </button>
                          <button
                            onClick={() => setModal(a)}
                            className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                            title="Hızlı Düzenle"
                          >
                            <Edit className="w-4 h-4" />
                          </button>
                          <button
                            onClick={() => setExitAnimal(a)}
                            className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                            title="Çıkış Yap / Durum Değiştir"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Mobile / Tablet Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 lg:hidden">
              {animals.map(a => (
                <div
                  key={a.id}
                  className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100 active:scale-[0.99] transition-transform"
                >
                  <div className="flex justify-between items-start mb-3">
                    <div onClick={() => navigate(`/animals/${a.id}?farm_id=${farmId}`)} className="cursor-pointer">
                      <h3 className="text-lg font-bold text-gray-900 leading-none hover:text-green-700">{a.name}</h3>
                      <p className="text-[10px] text-gray-400 font-mono mt-1 uppercase tracking-wider">{a.code}</p>
                    </div>
                    <span className={`badge ${STATUS_COLORS[a.status] || 'badge-info'} text-[10px]`}>
                      {STATUS_LABELS[a.status] || a.status}
                    </span>
                  </div>

                  <div className="grid grid-cols-2 gap-3 py-3 border-y border-gray-50 my-3">
                    <div>
                      <p className="text-[10px] text-gray-400 uppercase font-bold">Tür / Irk</p>
                      <p className="text-xs font-semibold text-gray-700">{a.species} / {a.breed || '—'}</p>
                    </div>
                    <div>
                      <p className="text-[10px] text-gray-400 uppercase font-bold">Cinsiyet</p>
                      <p className="text-xs font-semibold text-gray-700">{a.gender === 'F' ? '♀ Dişi' : '♂ Erkek'}</p>
                    </div>
                    <div>
                      <p className="text-[10px] text-gray-400 uppercase font-bold">Doğum</p>
                      <p className="text-xs font-semibold text-gray-700">{formatDate(a.birth_date)}</p>
                    </div>
                    <div>
                      <p className="text-[10px] text-gray-400 uppercase font-bold">Ağırlık</p>
                      <p className="text-xs font-semibold text-gray-700">{a.current_weight ? `${a.current_weight} kg` : '—'}</p>
                    </div>
                  </div>

                  <div className="flex gap-2">
                    <button
                      onClick={() => navigate(`/animals/${a.id}?farm_id=${farmId}`)}
                      className="flex-1 bg-green-50 text-green-700 font-bold py-2 rounded-xl text-xs flex items-center justify-center gap-1 hover:bg-green-100 transition-colors"
                    >
                      <Eye className="w-3.5 h-3.5" /> Detay
                    </button>
                    <button
                      onClick={() => setModal(a)}
                      className="bg-gray-50 text-gray-600 p-2 rounded-xl hover:bg-gray-100"
                      title="Düzenle"
                    >
                      <Edit className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => setExitAnimal(a)}
                      className="bg-red-50 text-red-600 p-2 rounded-xl hover:bg-red-100"
                      title="Çıkış / Sil"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
            </div>

            {/* Pagination */}
            {total > 50 && (
              <div className="flex items-center justify-between px-6 py-4 border-t border-gray-50 bg-gray-50/50 mt-4 rounded-b-2xl lg:mt-0">
                <p className="text-xs text-gray-500 font-medium">{total} kayıttan {animals.length} gösteriliyor</p>
                <div className="flex gap-2">
                  <button disabled={page === 1} onClick={() => setPage(p => p - 1)} className="btn-secondary text-xs py-1.5 px-4 disabled:opacity-40">←</button>
                  <span className="text-xs font-bold text-gray-700 self-center">Sayfa {page}</span>
                  <button disabled={animals.length < 50} onClick={() => setPage(p => p + 1)} className="btn-secondary text-xs py-1.5 px-4 disabled:opacity-40">→</button>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* Quick Add/Edit Modal */}
      {modal && (
        <AnimalModal
          animal={modal === 'add' ? null : modal}
          farmId={farmId}
          onClose={() => setModal(null)}
          onSaved={load}
        />
      )}

      {/* Exit / Status Change Modal */}
      {exitAnimal && (
        <ExitModal
          animal={exitAnimal}
          farmId={farmId}
          onClose={() => setExitAnimal(null)}
          onSaved={load}
        />
      )}
    </div>
  );
}
